"""New quantitative leaves, preserving the docket's ruled, pale surfaces and capsule geometry."""
from write_elements import write
import sys

def author(k):
 if k=='heatmap':
  css='''/* Inferred from replica16 aligned ruled rows and replica18 quiet gray surfaces. */
ROOT{container-type:size;container-name:od-heat;display:flex;flex-direction:column;justify-content:center;gap:calc(var(--gap-sm)/2);padding:1%;min-width:0;min-height:0;color:var(--ink)}ROOT>.heads{display:grid;grid-template-columns:repeat(var(--cols),minmax(0,1fr));margin-left:24%;gap:calc(var(--gap-sm)/2)}ROOT>.heads>span{text-align:center;font-size:var(--type-12);font-weight:var(--label-weight);line-height:var(--label-line);letter-spacing:var(--label-track);overflow-wrap:anywhere}ROOT>.row{display:grid;grid-template-columns:24% repeat(var(--cols),minmax(0,1fr));gap:calc(var(--gap-sm)/2);min-width:0;min-height:0}ROOT>.row>.name{align-self:center;margin:0;font-size:var(--type-14);font-weight:var(--body-weight);line-height:var(--body-line);letter-spacing:var(--body-track);overflow-wrap:anywhere}ROOT>.row>.cell{display:flex;align-items:center;justify-content:center;min-width:0;min-height:0;height:min(10cqh,44px);border-radius:var(--radius-sm);background:color-mix(in srgb,var(--a1) calc(var(--v)*1%),var(--n-1));padding:3px}ROOT>.row>.cell>b{display:inline-block;border-radius:var(--radius-sm);background:var(--page);color:var(--ink);padding:0 3px;font-size:var(--type-12);font-weight:var(--body-weight);line-height:var(--label-line);letter-spacing:var(--label-track)}ROOT.calendar>.heads{margin-left:0;align-self:center;inline-size:min(100%,calc(var(--cols)*45px + (var(--cols) - 1)*var(--gap-sm)/2))}ROOT.calendar>.row{grid-template-columns:repeat(var(--cols),minmax(0,1fr));align-self:center;inline-size:min(100%,calc(var(--cols)*45px + (var(--cols) - 1)*var(--gap-sm)/2))}ROOT.calendar>.row>.cell{aspect-ratio:1;height:auto;max-height:none}@container od-heat (max-width:500px){ROOT>.row>.name{font-size:var(--type-12)}}
'''
  vals=[[34,52,47,68],[72,61,79,84],[28,41,37,59],[63,76,69,91]]
  a='<div class="heat" DATA style="--cols:4"><div class="heads">'+''.join('<span>'+str(i+1)+'주</span>'for i in range(4))+'</div>'+''.join('<div class="row"><p class="name">'+name+'</p>'+''.join('<div class="cell" style="--v:'+str(v)+'"><b>'+str(v)+'</b></div>'for v in vs)+'</div>'for name,vs in zip(['접수 분류','승인 검토','담당 배정','이관 대조'],vals))+'</div>'
  b='<div class="heat calendar" DATA style="--cols:5"><div class="heads">'+''.join('<span>'+str(i+1)+'주</span>'for i in range(5))+'</div>'+''.join('<div class="row">'+''.join('<div class="cell" style="--v:'+str(v)+'"></div>'for v in vs)+'</div>'for vs in [[21,48,36,67,58],[38,64,71,57,82],[52,39,74,86,93]])+'</div>'
  write(k,'heat',css,'Measured rows of pale cells use accent strength as density. Values sit on small paper insets so every density remains readable in both modes. Calendar cells retain the same rounded geometry without row names.',[('weekly-density','6x4',a),('calendar-density','4x3',b)])
 elif k=='waffle':
  css='''/* Inferred from replica02 orderly numbered circles and replica15 pale circular fields. */
ROOT{container-type:size;container-name:od-waffle;display:grid;grid-template-columns:minmax(0,1fr);grid-template-rows:auto auto auto;align-content:center;justify-items:center;gap:var(--gap-sm);min-width:0;min-height:0;color:var(--ink)}ROOT>.units{display:grid;grid-template-columns:repeat(10,minmax(0,1fr));gap:4px;inline-size:min(90%,calc(65cqh * var(--od-waffle-ratio)),400px);aspect-ratio:var(--od-waffle-ratio);min-width:0;min-height:0;--od-waffle-count:100;--od-waffle-ratio:calc(10 / round(up,calc(var(--od-waffle-count)/10),1))}ROOT>.units>.u{position:relative;min-width:0;min-height:0;border-radius:50%;background:var(--n-2)}ROOT>.units>.u.on{background:var(--a1)}ROOT>.units>.u.tone-2{background:var(--a2)}ROOT>.fig{margin:0;font-size:clamp(var(--type-22),calc(5cqw),var(--type-36));font-weight:var(--figure-weight);line-height:var(--figure-line);letter-spacing:var(--figure-track)}ROOT>.name{margin:0;max-width:95%;font-size:var(--type-14);font-weight:var(--body-weight);line-height:var(--body-line);letter-spacing:var(--body-track);text-align:center;overflow-wrap:anywhere}ROOT.figures>.units>.u{background:none;border-radius:0}ROOT.figures>.units>.u::before{content:"";position:absolute;left:34%;top:0;width:32%;height:27%;border-radius:50%;background:var(--n-3)}ROOT.figures>.units>.u::after{content:"";position:absolute;inset:30% 14% 0;background:var(--n-3);clip-path:polygon(15% 0,85% 0,100% 45%,76% 50%,70% 100%,52% 100%,50% 58%,48% 100%,30% 100%,24% 50%,0 45%)}ROOT.figures>.units>.u.on::before,ROOT.figures>.units>.u.on::after{background:var(--a1)}
@container od-waffle (max-height:240px){ROOT>.units{inline-size:min(90%,calc(48cqh * var(--od-waffle-ratio)),400px)}ROOT>.fig{font-size:var(--type-24)}ROOT>.name{font-size:var(--type-12)}}
'''
  for n in range(10,101):css+=f'ROOT>.units:has(>.u:nth-child({n}):last-child){{--od-waffle-count:{n}}}'
  def row(n,count,figures=False):return '<div class="waffle'+(' figures'if figures else'')+'" DATA><div class="units">'+''.join('<span class="u'+(' on'if i<count else'')+'"></span>'for i in range(n))+'</div><p class="fig">'+str(count)+' / '+str(n)+'</p><p class="name">'+('승인 근거를 대조한 담당자'if figures else'이관 전 점검을 마친 접수 항목')+'</p></div>'
  write(k,'waffle',css,'Counted circles extend the orderly numbering language of replica02. Accent units show the counted share; the figures variant draws simple person silhouettes with the same rounded head and restrained body geometry.',[('share-hundred','4x3',row(100,73)),('people-ten','4x3',row(10,7,True))])
 elif k=='treemap':
  css='''/* Inferred from replica18 gray split bays and replica16 fine internal rules. */
ROOT{container-type:size;container-name:od-treemap;display:flex;align-items:stretch;gap:2px;min-width:0;min-height:0;padding:1%;color:var(--ink)}ROOT>.branch{display:flex;flex-direction:column;flex:var(--v) 1 0;gap:2px;min-width:0;min-height:0;background:var(--n-2)}ROOT>.branch>.name{margin:0;padding:var(--gap-sm);font-size:var(--type-14);font-weight:var(--name-weight);line-height:var(--name-line);letter-spacing:var(--name-track);overflow-wrap:anywhere}ROOT>.branch>.tile{display:flex;flex-direction:column;justify-content:center;gap:calc(var(--gap-sm)/2);flex:var(--v) 1 0;min-width:0;min-height:0;padding:0;background:var(--n-1)}ROOT>.branch>.tile>.name{margin:0;padding-inline:var(--gap-sm);font-size:var(--type-14);font-weight:var(--body-weight);line-height:var(--body-line);letter-spacing:var(--body-track);overflow-wrap:anywhere}ROOT>.branch>.tile>.fig{margin:0;padding-inline:var(--gap-sm);font-size:var(--type-22);font-weight:var(--figure-weight);line-height:var(--figure-line);letter-spacing:var(--figure-track)}ROOT>.branch>.tile.on{background:var(--a1);color:var(--a1-on)}@container od-treemap (max-width:600px){ROOT>.branch>.name,ROOT>.branch>.tile>.name{font-size:var(--type-12)}ROOT>.branch>.tile>.fig{font-size:var(--type-18)}}
'''
  def row(two=False):
   groups=[('고객 접점',60,[('상담 접수',55),('운영 이관',45)])]+([('승인 처리',40,[('예외 검토',62),('후속 대조',38)])]if two else[])
   return '<div class="treemap" DATA>'+''.join('<div class="branch" style="--v:'+str(v)+'"><p class="name">'+name+'</p>'+''.join('<div class="tile'+(' on'if i==0 and name=='고객 접점' else'')+'" style="--v:'+str(tv)+'"><p class="name">'+tn+'</p><p class="fig">'+str(tv)+'%</p></div>'for i,(tn,tv) in enumerate(tiles))+'</div>'for name,v,tiles in groups)+'</div>'
  write(k,'treemap',css,'Proportional branches contain proportional quiet tiles. A separate ruled branch heading and one accent tile keep the split-bay language legible while preserving the actual area shares.',[('one-branch','4x4',row()),('two-branches','6x4',row(True))])
 elif k=='chart-scatter':
  css='''/* Inferred from replica17 bare labels and replica02 small circles, with replica16 axis rules. */
ROOT{container-type:size;container-name:od-scatter;position:relative;min-width:0;min-height:0;color:var(--ink)}ROOT::before{content:"";position:absolute;left:54px;right:40px;top:30px;bottom:45px;border-left:var(--stroke) solid var(--n-4);border-bottom:var(--stroke) solid var(--n-4)}ROOT>.axis-x{position:absolute;bottom:0;left:54px;right:40px;text-align:center}ROOT>.axis-y{position:absolute;left:0;top:2px;right:40px}ROOT>.axis-x>span,ROOT>.axis-y>span{font-size:var(--type-12);font-weight:var(--body-weight);line-height:var(--label-line);letter-spacing:var(--body-track);color:var(--n-7)}ROOT>.dot{position:absolute;left:calc(54px + (100% - 94px)*var(--x)/var(--xmax));top:calc(100% - 45px - (100% - 75px)*var(--y)/var(--ymax));width:10px;height:10px;transform:translate(-50%,-50%);border-radius:50%;background:var(--n-5)}ROOT>.dot.on{background:var(--a1)}ROOT>.dot.tone-2{background:var(--a2)}ROOT>.dot.tone-3{background:var(--a3)}ROOT>.dot>span{position:absolute;bottom:calc(100% + 5px);left:50%;transform:translateX(-50%);white-space:nowrap;font-size:var(--type-12);font-weight:var(--body-weight);line-height:var(--label-line);letter-spacing:var(--body-track)}ROOT.bubble>.dot{width:calc(10px + var(--r)*.5px);height:calc(10px + var(--r)*.5px);background:var(--a1-2-soft);border:var(--stroke) solid var(--a1-7)}ROOT.bubble>.dot.on{background:var(--a1)}
'''
  def row(bubble=False):return '<div class="scatter'+(' bubble'if bubble else'')+'" DATA style="--xmax:100;--ymax:100"><div class="axis-x"><span>자동 분류 비중</span></div><div class="axis-y"><span>첫 응답 준수율</span></div>'+''.join('<div class="dot'+(' on'if i==2 else'')+'" style="--x:'+str(x)+';--y:'+str(y)+';--r:'+str(r)+'"><span>'+name+'</span></div>'for i,(name,x,y,r) in enumerate([('온라인',22,64,38),('전화',47,38,57),('이관',73,81,72),('현장',86,51,46)][:4 if bubble else 3]))+'</div>'
  write(k,'scatter',css,'Small circular observations sit on two fine value axes. Plain labels remain outside their marks; bubble size expresses the third value with a pale fill and thin accent edge.',[('channel-scatter','6x3',row()),('channel-bubbles','8x4',row(True))])
 elif k=='chart-waterfall':
  css='''/* Inferred from replica17 open numeric hierarchy and replica10 connected step rhythm. */
ROOT{container-type:size;container-name:od-waterfall;display:flex;gap:var(--gap-sm);padding:0 3%;min-width:0;min-height:0;color:var(--ink)}ROOT>.move{position:relative;flex:1;min-width:0;min-height:0}ROOT>.move::before{content:"";position:absolute;left:22%;right:22%;bottom:calc(36px + (100cqh - 76px)*min(var(--from),var(--to))/var(--max));height:calc((100cqh - 76px)*abs(var(--to) - var(--from))/var(--max));border-radius:var(--radius-sm);background:var(--n-4)}ROOT>.move.down::before{background:var(--n-2);border:var(--stroke) solid var(--n-5)}ROOT>.move.total::before{bottom:36px;height:calc((100cqh - 76px)*var(--to)/var(--max));background:var(--a1)}ROOT>.move:not(:last-child)::after{content:"";position:absolute;left:78%;right:calc(-22% - var(--gap-sm));bottom:calc(36px + (100cqh - 76px)*var(--to)/var(--max));height:1px;background:var(--n-4)}ROOT>.move>b{position:absolute;left:0;right:0;bottom:calc(40px + (100cqh - 76px)*max(var(--from),var(--to))/var(--max));text-align:center;font-size:var(--type-14);font-weight:var(--name-weight);line-height:var(--label-line);letter-spacing:var(--label-track);white-space:nowrap}ROOT>.move>span{position:absolute;bottom:0;left:0;right:0;height:28px;text-align:center;font-size:var(--type-12);font-weight:var(--body-weight);line-height:var(--label-line);letter-spacing:var(--body-track);overflow-wrap:anywhere}@container od-waterfall (max-width:600px){ROOT>.move>b{font-size:var(--type-12)}}
'''
  def row(long=False):
   vals=[('기초 물량',0,128,'total'),('신규 접수',128,186,'up'),('중복 제외',186,164,'down'),('추가 이관',164,203,'up'),('처리 대상',0,203,'total')]
   if long:vals=[('이월 건수',0,94,'total'),('월간 접수',94,162,'up'),('취소 요청',162,147,'down'),('예외 이관',147,179,'up'),('중복 제거',179,168,'down'),('최종 물량',0,168,'total')]
   return '<div class="waterfall" DATA style="--max:240">'+''.join('<div class="move '+t+'" style="--from:'+str(a)+';--to:'+str(b)+'"><b>'+str(b if t=='total'else b-a)+'</b><span>'+n+'</span></div>'for n,a,b,t in vals)+'</div>'
  write(k,'waterfall',css,'Floating rounded rectangles preserve running totals. A thin connector follows each ending total, decreases use an outlined quiet material and total bars take the accent role.',[('monthly-queue','6x3',row()),('monthly-review','8x4',row(True))])
 else:raise SystemExit(k)
if __name__=='__main__':author(sys.argv[1])
